1. **Presale Contract**:
   - This contract will handle the presale phase, including token distribution and collecting funds.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

contract TokenPresale {
    ERC20 public immutable token;
    address public immutable wallet;
    uint256 public immutable startTime;
    uint256 public immutable endTime;
    uint256 public immutable price;
    uint256 public immutable maxTokens;
    uint256 public tokensSold;
    mapping(address => uint256) public investedAmount;

    event TokensPurchased(address indexed buyer, uint256 amount);

    constructor(
        ERC20 _token,
        address _wallet,
        uint256 _startTime,
        uint256 _endTime,
        uint256 _price,
        uint256 _maxTokens
    ) {
        token = _token;
        wallet = _wallet;
        startTime = _startTime;
        endTime = _endTime;
        price = _price;
        maxTokens = _maxTokens;
    }

    modifier withinSalePeriod() {
        require(block.timestamp >= startTime && block.timestamp <= endTime, "Sale not active");
        _;
    }

    function buyTokens(uint256 _amount) public withinSalePeriod payable {
        require(msg.value == _amount * price, "Incorrect amount sent");
        require(tokensSold + _amount <= maxTokens, "Exceeds maximum tokens for sale");
        require(investedAmount[msg.sender] + msg.value <= msg.value, "Exceeds maximum investment");

        investedAmount[msg.sender] += msg.value;
        tokensSold += _amount;

        token.transfer(msg.sender, _amount);
        (bool sent, ) = wallet.call{value: msg.value}("");
        require(sent, "Failed to send Ether");

        emit TokensPurchased(msg.sender, _amount);
    }
}
```

2. **Main Contract**:
   - This contract will handle the main functionality of your token after the presale is over.

```solidity
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";

contract Token {
    ERC20 public immutable token;
    address public immutable presaleContract;
    uint256 public immutable startTime;
    uint256 public immutable endTime;
    uint256 public immutable price;
    uint256 public immutable maxTokens;

    constructor(
        ERC20 _token,
        address _presaleContract,
        uint256 _startTime,
        uint256 _endTime,
        uint256 _price,
        uint256 _maxTokens
    ) {
        token = _token;
        presaleContract = _presaleContract;
        startTime = _startTime;
        endTime = _endTime;
        price = _price;
        maxTokens = _maxTokens;
    }

    modifier afterPresale() {
        require(block.timestamp > endTime, "Presale is still active");
        _;
    }

    function claimTokens() public afterPresale {
        uint256 tokensToClaim = token.balanceOf(presaleContract);
        token.transfer(msg.sender, tokensToClaim);
    }
}
