3. Implement the `convert_markdown_to_html` function in `main.cpp`:
```cpp
#include <iostream>
#include <string>
#include <markdown/cpp/markdown.hpp>
#include <pugixml.hpp>

std::string convert_markdown_to_html(const std::string& markdown) {
    // Convert markdown to HTML using markdown_cpp
    std::string html = markdown_cpp::markdown(markdown);

    // Parse HTML using pugixml
    pugi::xml_document doc;
    doc.load_string(html.c_str());

    // Transform HTML to the desired format
    // For example, add a header and a footer
    pugi::xml_node head = doc.child("head");
    head.append_child("title").append_child(pugi::node_pcdata).set_value("Converted Markdown");

    pugi::xml_node body = doc.child("body");
    body.prepend_child(pugi::node_pcdata).set_value("Converted from Markdown:\n\n");
    body.append_child(pugi::node_pcdata).set_value("\n\n---\n\n");

    // Generate the modified HTML
    std::string modified_html;
    doc.print(modified_html, "", PUGI_XML_PFORMAT_PRETTY);

    return modified_html;
}

int main() {
    std::string markdown = "## This is a header\n\nThis is a paragraph.";
    std::string html = convert_markdown_to_html(markdown);
    std::cout << html << std::endl;

    return 0;
}
